MAX_DEPTH = 3


class DelegationRefused(Exception):
    pass


def spawn_agent(task: str, depth: int, budget) -> str:
    if depth >= MAX_DEPTH or budget.remaining_agents <= 0:
        raise DelegationRefused('delegation budget exhausted')
    budget.remaining_agents -= 1
    return agent_run(task, tools=[search], depth=depth + 1, budget=budget)
